// lib/db.ts — DATABASE_URL → pgbouncer (transaction mode)
import postgres from 'postgres';

export const sql = postgres(process.env.DATABASE_URL!, {
  max: 10,         // plenty of headroom per instance
  idle_timeout: 0, // keep connections forever, avoid re-dialing
});

export async function onPriceChange(cb: (id: string) => void) {
  await sql.listen('price_changed', (payload) => cb(payload));
}

export async function getProduct(id: string) {
  return sql`select * from products where id = ${id}`;
}
